export const DIGITAL_ETIQUETTE_ACTIVITIES = [
// FASE A — FONDASI / KONKRET (1-20): apa itu etiket digital
{n:1,type:"mcq",micro:"Apa itu etiket digital",q:"'Etiket digital' (netiquette) adalah...",options:["Aturan tak tertulis tentang bersikap sopan & menghormati orang lain saat berinteraksi lewat internet","Aturan resmi yang ditulis pemerintah untuk semua aplikasi","Cara mengetik secepat mungkin"],answer:0,explain:"Sama seperti sopan santun di dunia nyata, etiket digital membantu interaksi online tetap nyaman & saling menghormati.",hint:"Sopan santun online, atau aturan resmi pemerintah?"},
{n:2,type:"mcq",micro:"Teks kehilangan nada suara",q:"Kenapa pesan teks lebih mudah disalahpahami dibanding bicara langsung?",options:["Orang selalu membaca pesan dengan sangat teliti","Teks tidak membawa nada suara, ekspresi wajah, atau bahasa tubuh yang biasanya membantu memahami maksud","Teks selalu lebih jelas daripada bicara langsung"],answer:1,explain:"'Terserah.' bisa terdengar santai atau ketus tergantung nada suara, tapi lewat teks pembaca harus menebak-nebak maksudnya.",hint:"Kehilangan nada & ekspresi, atau selalu lebih jelas?"},
{n:3,type:"mcq",micro:"HURUF BESAR SEMUA",q:"Menulis pesan dengan SEMUA HURUF BESAR biasanya dipahami sebagai...",options:["Cara menulis yang sopan & formal","Tidak punya arti khusus","Berteriak atau sangat marah, meski maksud penulis mungkin berbeda"],answer:2,explain:"Konvensi umum di dunia digital: huruf besar semua = kesan berteriak. Perlu hati-hati memakainya kecuali memang untuk menekankan sesuatu.",hint:"Kesan berteriak/marah, atau sopan & formal?"},
{n:4,type:"mcq",micro:"Membaca sebelum mengirim",q:"Kebiasaan membaca ulang pesan sebelum mengirim membantu karena...",options:["Memberi kesempatan menilai apakah nadanya sesuai maksud & tidak akan disalahpahami","Membuang waktu tanpa manfaat","Tidak berpengaruh pada cara pesan diterima"],answer:0,explain:"Sekali terkirim, pesan (& kesan yang ditimbulkannya) sudah dilihat orang. Membaca ulang mencegah salah paham yang bisa dihindari.",hint:"Menilai nada sebelum terkirim, atau tak berpengaruh?"},
{n:5,type:"mcq",micro:"Menghormati waktu orang lain",q:"Mengirim pesan panjang tengah malam yang meminta jawaban 'sekarang juga' kurang menghormati karena...",options:["Malam hari adalah waktu terbaik untuk pesan penting","Tidak semua orang online 24 jam, & mengharapkan respons instan mengabaikan waktu istirahat orang lain","Semua orang wajib online setiap saat"],answer:1,explain:"Kecuali darurat, memberi ruang waktu wajar bagi orang membalas adalah bentuk menghargai kehidupan mereka di luar layar.",hint:"Mengabaikan waktu istirahat orang, atau semua wajib online?"},
{n:6,type:"mcq",micro:"Menyapa & memperkenalkan diri",q:"Saat menghubungi seseorang yang belum pernah kamu ajak bicara (mis. guru, orang dewasa), etiket yang baik:",options:["Langsung tanya inti masalah tanpa basa-basi apa pun","Kirim pesan tanpa salam berkali-kali sampai dibalas","Sapa dengan sopan, perkenalkan diri, & jelaskan maksud singkat sebelum masuk ke inti"],answer:2,explain:"Salam & perkenalan singkat membuat penerima tahu siapa yang menghubungi & konteksnya, terutama untuk orang yang belum kenal kita.",hint:"Sapa & perkenalkan diri, atau langsung inti / kirim berkali-kali?"},
{n:7,type:"mcq",micro:"Grup chat & pesan berlebihan",q:"Mengirim banyak pesan pendek terpisah ('Halo' 'Ada' 'Yang' 'Mau' 'Ditanya') alih-alih satu pesan utuh bisa...",options:["Membuat notifikasi orang lain berbunyi berkali-kali & terasa mengganggu","Selalu lebih sopan","Tidak berpengaruh sama sekali"],answer:0,explain:"Menggabungkan jadi satu pesan yang jelas lebih menghormati waktu & perhatian orang lain dibanding memecahnya jadi banyak notifikasi.",hint:"Mengganggu dengan notifikasi berkali-kali, atau selalu lebih sopan?"},
{n:8,type:"mcq",micro:"Emoji membantu nada",q:"Emoji dalam pesan bisa membantu karena...",options:["Membuat pesan jadi lebih sulit dipahami","Memberi petunjuk nada/perasaan yang hilang dari teks polos, mengurangi risiko salah paham","Selalu wajib dipakai di setiap kalimat"],answer:1,explain:"'Oke.' vs 'Oke! 😊' bisa terasa sangat berbeda nadanya. Emoji yang tepat membantu menyampaikan maksud dengan lebih jelas.",hint:"Membantu petunjuk nada, atau wajib di tiap kalimat?"},
{n:9,type:"order",micro:"Menulis pesan yang jelas & sopan",q:"Urutkan langkah menulis pesan penting ke seseorang.",items:["Pikirkan tujuan pesan: apa yang ingin disampaikan/ditanyakan","Tulis dengan sapaan & bahasa yang sesuai konteks (formal/santai)","Baca ulang: apakah jelas & nadanya sesuai maksud?","Kirim, & beri waktu wajar untuk dibalas"],answer:[0,1,2,3],explain:"Tujuan jelas → tulis sesuai konteks → periksa ulang → kirim & beri waktu. Membaca ulang sebelum kirim mencegah banyak kesalahpahaman.",hint:"Membaca ulang dilakukan sebelum atau sesudah mengirim?"},
{n:10,type:"mcq",micro:"Etiket berbeda tiap platform",q:"Gaya bahasa yang cocok di grup chat santai dengan teman berbeda dari yang cocok untuk...",options:["Semua tempat harus memakai gaya yang sama persis","Etiket tidak pernah berubah tergantung tempat","Pesan ke guru/orang dewasa atau forum resmi, yang biasanya butuh bahasa lebih sopan & formal"],answer:2,explain:"Menyesuaikan gaya bahasa dengan konteks & audiens adalah bagian penting dari etiket digital yang baik.",hint:"Menyesuaikan konteks, atau selalu sama di semua tempat?"},
{n:11,type:"tf",micro:"Sopan santun tetap berlaku online",q:"Benar atau Salah: Aturan dasar sopan santun (menghormati, tidak menghina, mendengarkan) tetap berlaku saat berkomunikasi lewat internet, meski tidak bertatap muka langsung.",answer:true,explain:"Layar tidak menghapus kebutuhan akan rasa hormat. Orang di ujung sana tetap manusia dengan perasaan.",hint:"Tetap berlaku, atau hilang karena tidak tatap muka?"},
{n:12,type:"tf",micro:"Semua orang online berarti tersedia",q:"Benar atau Salah: Tanda 'online' di sebuah aplikasi berarti orang itu wajib membalas pesanmu saat itu juga.",answer:false,explain:"Sebaliknya, 'online' hanya berarti aplikasinya aktif, tidak berarti orang itu sedang bebas atau wajib membalas segera. Ia mungkin sedang sibuk dengan hal lain.",hint:"Wajib membalas segera, atau tidak berarti harus segera?"},
{n:13,type:"mcq",micro:"Meminta maaf di dunia digital",q:"Kalau kamu tidak sengaja mengirim pesan yang menyinggung, sikap yang baik:",options:["Minta maaf dengan tulus secepat mungkin, sama seperti kalau itu terjadi tatap muka","Menghapus pesan & berharap tidak ada yang sadar","Menyalahkan orang yang tersinggung karena 'terlalu sensitif'"],answer:0,explain:"Kesalahan tetap kesalahan, di dunia digital maupun nyata. Permintaan maaf yang tulus membantu memperbaiki hubungan.",hint:"Minta maaf tulus, atau hapus diam-diam / salahkan orang lain?"},
{n:14,type:"mcq",micro:"Menghormati privasi dalam percakapan",q:"Menyebarkan tangkapan layar percakapan pribadi ke orang lain tanpa izin (kecuali darurat/keselamatan) adalah...",options:["Tidak berhubungan dengan etiket sama sekali","Melanggar kepercayaan orang yang mengira percakapannya privat","Selalu boleh dilakukan tanpa perlu izin"],answer:1,explain:"Percakapan yang dianggap privat oleh pengirimnya perlu dihormati batasnya, kecuali ada alasan penting seperti keselamatan.",hint:"Melanggar kepercayaan, atau selalu boleh?"},
{n:15,type:"mcq",micro:"Mengoreksi kesalahan orang lain",q:"Kalau seseorang membuat kesalahan ketik atau salah info di komentar publik, cara yang sopan menanggapinya:",options:["Ejek di depan banyak orang agar 'malu & belajar'","Diamkan meski itu penting untuk dikoreksi","Beri tahu dengan baik, fokus pada info, bukan mempermalukan orangnya"],answer:2,explain:"Koreksi yang sopan membantu tanpa merendahkan. Ejekan publik sering membuat orang defensif, bukan berterima kasih.",hint:"Koreksi baik & fokus info, atau ejek / diamkan?"},
{n:16,type:"tf",micro:"Etiket berlaku untuk semua usia",q:"Benar atau Salah: Etiket digital hanya berlaku untuk orang dewasa; anak-anak & remaja tidak perlu memikirkannya.",answer:false,explain:"Sebaliknya, etiket digital berlaku untuk semua orang tidak peduli usia, karena semua yang berinteraksi online sama-sama layak dihormati.",hint:"Berlaku untuk semua usia, atau hanya orang dewasa?"},
{n:17,type:"mcq",micro:"Membalas dengan tepat waktu wajar",q:"Standar 'wajar' untuk membalas pesan biasa (bukan darurat) tergantung pada...",options:["Konteks & kebiasaan yang disepakati (kerja/sekolah biasanya lebih cepat, santai bisa lebih santai), tidak ada aturan mutlak 'harus dalam X menit'","Harus selalu dalam 1 menit tanpa kecuali","Tidak ada bedanya, semua pesan sama pentingnya"],answer:0,explain:"Yang penting adalah kesadaran & rasa hormat, bukan angka pasti. Konteks membentuk ekspektasi yang wajar.",hint:"Tergantung konteks, atau harus selalu 1 menit?"},
{n:18,type:"mcq",micro:"Menyapa dengan nama yang benar",q:"Memastikan menulis nama orang dengan ejaan yang benar saat berkomunikasi menunjukkan...",options:["Hanya perlu untuk orang penting","Perhatian & rasa hormat kecil yang berarti bagi penerimanya","Tidak penting sama sekali"],answer:1,explain:"Detail kecil seperti ejaan nama yang benar menunjukkan kamu memperhatikan & menghargai orangnya.",hint:"Perhatian & rasa hormat, atau tidak penting?"},
{n:19,type:"mcq",micro:"Menghindari spam",q:"Mengirim pesan/tag yang sama berulang-ulang ke banyak orang tanpa relevansi (spam) itu...",options:["Cara efektif menyebarkan info","Tidak masalah selama niatnya baik","Mengganggu & tidak sopan, karena membebani perhatian orang tanpa nilai yang sepadan"],answer:2,explain:"Membanjiri orang dengan pesan berulang tanpa nilai jelas mengganggu, meski niatnya baik.",hint:"Mengganggu & tidak sopan, atau efektif / tidak masalah?"},
{n:20,type:"open",micro:"Perbaiki sebuah pesan",q:"Pesan asli yang akan dikirim ke guru: 'bu, tugas kmrn kok blm dinilai? cepetan dong butuh buat nilai rapot'. Tulis ulang pesan ini agar lebih sopan & sesuai etiket digital yang baik, lalu jelaskan minimal 3 perubahan yang kamu buat & alasannya.",sample:"Pesan yang diperbaiki: 'Selamat sore, Bu. Mohon maaf mengganggu waktunya. Saya [nama], izin bertanya apakah tugas yang saya kumpulkan kemarin sudah bisa dinilai? Saya membutuhkannya untuk keperluan nilai rapor. Terima kasih banyak, Bu 🙏' Perubahan: (1) Menambahkan salam pembuka ('Selamat sore, Bu') & permintaan maaf sopan ('mohon maaf mengganggu'), karena pesan asli langsung ke inti tanpa sapaan sama sekali, terasa kasar untuk pesan ke guru. (2) Mengganti bahasa gaul/singkatan ('kmrn', 'blm', 'cepetan dong') menjadi bahasa baku & lengkap, karena komunikasi dengan guru biasanya butuh bahasa yang lebih formal & jelas, singkatan berlebihan terkesan tidak menghormati. (3) Mengganti nada mendesak ('cepetan dong butuh') menjadi permintaan yang sopan & menjelaskan alasan ('izin bertanya... saya membutuhkannya untuk...'), karena nada mendesak bisa terasa menuntut, padahal guru mungkin punya alasan wajar & banyak tugas untuk dinilai. (4) Menambahkan penutup terima kasih untuk menunjukkan rasa hormat & mengakhiri pesan dengan baik.",explain:"Jawaban baik: pesan yang ditulis ulang benar-benar lebih sopan, formal, & jelas (bukan sekadar menambah 'Bu' di depan), & minimal 3 perubahan yang disebut dengan alasan spesifik yang menunjukkan pemahaman tentang kenapa perubahan itu penting.",hint:"Perhatikan tiga hal dalam pesan asli: tidak ada sapaan, bahasa terlalu santai/singkatan, & nada yang terdengar menuntut/mendesak."},

// FASE B — PEMAHAMAN (21-40): konteks platform, grup chat, kesalahpahaman
{n:21,type:"classify",micro:"Sopan vs kurang sopan dalam pesan",q:"Kelompokkan tiap kebiasaan ke 'Sopan' atau 'Kurang sopan'.",items:["Membaca ulang pesan sebelum mengirim ke guru","Mengirim 10 pesan terpisah tengah malam meminta balasan segera","Menyapa & memperkenalkan diri saat menghubungi orang baru","Menuliskan semua kalimat dengan HURUF BESAR tanpa alasan"],groups:["Sopan","Kurang sopan"],answer:{"Sopan":["Membaca ulang pesan sebelum mengirim ke guru","Menyapa & memperkenalkan diri saat menghubungi orang baru"],"Kurang sopan":["Mengirim 10 pesan terpisah tengah malam meminta balasan segera","Menuliskan semua kalimat dengan HURUF BESAR tanpa alasan"]},explain:"Sopan: memeriksa nada, memperkenalkan diri. Kurang sopan: membebani dengan notifikasi berlebihan & terkesan berteriak.",hint:"Menghormati waktu & memperkenalkan diri, atau membebani & terkesan berteriak?"},
{n:22,type:"mcq",micro:"Etiket grup chat besar",q:"Di grup chat besar (kelas, keluarga besar), kebiasaan yang membantu semua nyaman:",options:["Kirim pesan yang relevan untuk semua anggota, hindari obrolan pribadi berlarut yang tidak perlu dilihat semua orang","Kirim apa pun kapan pun karena grup untuk semua orang","Selalu balas dengan stiker/emoji tanpa isi apa pun"],answer:0,explain:"Grup besar butuh kesadaran bahwa banyak orang menerima notifikasi. Obrolan pribadi lebih baik dipindah ke chat langsung.",hint:"Relevan untuk semua & hindari obrolan pribadi, atau kirim bebas / stiker kosong?"},
{n:23,type:"mcq",micro:"Memindahkan obrolan pribadi",q:"Kalau percakapan di grup mulai jadi obrolan panjang hanya antara dua orang, etiket yang baik:",options:["Minta semua orang keluar dari grup sementara","Pindahkan ke pesan pribadi supaya tidak membanjiri notifikasi anggota lain yang tidak terlibat","Lanjutkan di grup karena lebih cepat"],answer:1,explain:"Memindahkan obrolan yang hanya relevan untuk sebagian orang menghormati waktu & perhatian anggota lain.",hint:"Pindahkan ke pesan pribadi, atau lanjutkan di grup?"},
{n:24,type:"mcq",micro:"Reaksi berlebihan pada kesalahan kecil",q:"Seseorang salah ketik atau membuat kesalahan kecil di grup. Respons yang sesuai etiket:",options:["Menyoroti & mengejeknya berulang kali di grup","Mengeluarkannya dari grup","Biarkan saja atau beri tahu dengan santai bila perlu; kesalahan kecil tidak perlu ditanggapi berlebihan"],answer:2,explain:"Menanggapi kesalahan kecil secara proporsional (bukan berlebihan) menjaga suasana grup tetap nyaman untuk semua.",hint:"Tanggapi proporsional, atau mengejek berulang / keluarkan?"},
{n:25,type:"mcq",micro:"Video call etiquette",q:"Sebelum panggilan video (kelas daring, rapat), kebiasaan sopan:",options:["Pastikan latar belakang & penampilan wajar, & datang tepat waktu, seperti menghadiri pertemuan tatap muka","Bisa dilakukan sambil melakukan hal lain tanpa perlu bersiap","Tidak perlu peduli latar belakang atau waktu"],answer:0,explain:"Meski lewat layar, panggilan video tetap 'pertemuan'. Kesiapan menunjukkan penghormatan pada peserta lain.",hint:"Bersiap & tepat waktu seperti tatap muka, atau bebas tanpa persiapan?"},
{n:26,type:"mcq",micro:"Mematikan mikrofon saat tidak bicara",q:"Mematikan mikrofon (mute) saat tidak sedang berbicara di panggilan grup berguna untuk...",options:["Tidak ada manfaatnya","Mengurangi suara latar yang mengganggu peserta lain mendengar dengan jelas","Membuat kamu terlihat tidak sopan"],answer:1,explain:"Suara latar yang tidak disengaja bisa mengganggu semua orang di panggilan. Mute saat diam adalah kebiasaan sopan yang umum.",hint:"Mengurangi gangguan suara latar, atau tidak sopan / tak bermanfaat?"},
{n:27,type:"tf",micro:"Etiket berbeda di forum publik vs chat pribadi",q:"Benar atau Salah: Cara berkomunikasi yang pantas seharusnya selalu sama persis, baik di komentar publik maupun chat pribadi dengan teman dekat.",answer:false,explain:"Sebaliknya, komentar publik dilihat lebih banyak orang termasuk yang tidak dikenal, biasanya butuh kehati-hatian & kesopanan lebih dibanding obrolan pribadi.",hint:"Berbeda formalitas tergantung konteks, atau selalu sama di mana pun?"},
{n:28,type:"tf",micro:"Diam saat orang lain bicara",q:"Benar atau Salah: Dalam panggilan video grup, memotong pembicaraan orang lain berulang kali dianggap wajar & tidak masalah karena aturannya berbeda dari pertemuan tatap muka.",answer:false,explain:"Sebaliknya, etiket mendengarkan & bergiliran bicara berlaku sama pentingnya lewat layar seperti tatap muka langsung; memotong berulang tetap dianggap kurang sopan.",hint:"Kurang sopan sama seperti tatap muka, atau berbeda aturan lewat layar?"},
{n:29,type:"mcq",micro:"Menandai (tag) orang lain",q:"Menandai (mention/tag) seseorang di unggahan publik yang membuat mereka terlihat buruk tanpa alasan penting itu...",options:["Selalu boleh dilakukan tanpa berpikir dampaknya","Tidak masalah selama lucu bagi yang menandai","Kurang sopan; sebaiknya pikirkan dampaknya pada orang yang ditandai sebelum melakukannya"],answer:2,explain:"Menandai seseorang menarik perhatian ke mereka. Memikirkan dampaknya (terutama kalau berpotensi mempermalukan) adalah bagian etiket digital.",hint:"Pikirkan dampaknya dulu, atau selalu boleh / tak masalah?"},
{n:30,type:"order",micro:"Menangani obrolan yang mulai kacau",q:"Urutkan langkah menangani grup chat yang mulai penuh perdebatan/kekacauan.",items:["Sadari suasana mulai tidak nyaman bagi banyak anggota","Sampaikan dengan baik untuk menenangkan atau mengarahkan kembali ke topik","Bila perlu, ajak pihak yang berselisih membahas secara pribadi","Jaga agar grup tetap nyaman untuk anggota lain yang tidak terlibat"],answer:[0,1,2,3],explain:"Sadari suasana → tenangkan/arahkan → pindahkan konflik ke privat bila perlu → jaga kenyamanan bersama. Konflik dua orang tidak perlu jadi tontonan semua anggota.",hint:"Memindahkan pihak yang berselisih ke privat sebelum atau sesudah menyampaikan penenang di grup?"},
{n:31,type:"mcq",micro:"Bahasa yang sesuai audiens",q:"Bahasa gaul/singkatan yang biasa dipakai dengan teman sebaya sebaiknya disesuaikan saat berkomunikasi dengan...",options:["Guru, orang dewasa, atau dalam konteks resmi/sekolah, yang biasanya mengharapkan bahasa lebih baku","Semua orang harus memakai bahasa yang sama persis di mana pun","Tidak perlu disesuaikan sama sekali"],answer:0,explain:"Menyesuaikan register bahasa dengan audiens & konteks adalah keterampilan komunikasi dasar yang juga berlaku di dunia digital.",hint:"Sesuaikan dengan audiens formal, atau selalu sama?"},
{n:32,type:"tf",micro:"Balasan singkat bisa terkesan ketus",q:"Benar atau Salah: Balasan sangat singkat ('Ya.' 'Terserah.' 'Ok.') selalu dipahami dengan nada netral oleh penerimanya, tidak mungkin disalahartikan.",answer:false,explain:"Sebaliknya, karena teks kehilangan nada suara, balasan super singkat kadang bisa terkesan ketus atau dingin meski maksudnya tidak begitu. Menambah sedikit konteks/emoji bisa membantu.",hint:"Bisa terkesan ketus tanpa maksud begitu, atau selalu dipahami netral?"},
{n:33,type:"mcq",micro:"Menghormati kanal komunikasi yang tepat",q:"Untuk hal penting/mendesak (mis. keadaan darurat), lebih efektif memakai...",options:["Menunggu bertemu langsung meski darurat","Telepon atau panggilan langsung, karena pesan teks bisa tidak segera dilihat","Selalu pesan teks kapan pun tanpa kecuali"],answer:1,explain:"Etiket digital juga soal memilih kanal yang tepat untuk kepentingannya, bukan hanya sopan santun dalam menulis.",hint:"Telepon untuk hal mendesak, atau selalu teks / tunggu tatap muka?"},
{n:34,type:"mcq",micro:"Meme & humor yang tidak menyakiti",q:"Meme atau lelucon yang menyindir kelompok/individu tertentu secara kasar berbeda dari humor yang sehat karena...",options:["Selalu lucu bagi semua orang tanpa terkecuali","Tidak ada bedanya sama sekali","Bisa menyakiti orang sungguhan, meski dibuat 'hanya bercanda'"],answer:2,explain:"'Cuma bercanda' tidak menghapus dampak nyata pada perasaan orang yang menjadi sasaran. Humor yang sehat tidak merendahkan orang sungguhan.",hint:"Bisa menyakiti meski 'bercanda', atau selalu lucu / tak ada bedanya?"},
{n:35,type:"mcq",micro:"Memberi kredit saat membagikan karya",q:"Membagikan karya/foto/tulisan orang lain tanpa menyebut siapa pembuatnya adalah...",options:["Kurang menghargai usaha pembuatnya; menyebut sumber/kredit adalah bentuk etiket & penghormatan","Wajar & tidak perlu dipikirkan","Hanya penting untuk karya yang sangat terkenal"],answer:0,explain:"Menyebut kredit ('dari akun X' atau 'karya Y') menghormati usaha pembuat & menjaga transparansi tentang asal sesuatu.",hint:"Kurang menghargai tanpa kredit, atau wajar tanpa perlu?"},
{n:36,type:"mcq",micro:"Menyela dengan sopan",q:"Kalau kamu perlu menyela percakapan grup untuk hal penting, cara yang sopan:",options:["Kirim pesan berulang sampai orang lain berhenti membahas topik mereka","Beri sedikit peringatan ('maaf menyela sebentar') sebelum masuk ke topik berbeda","Langsung ganti topik tanpa keterangan apa pun"],answer:1,explain:"Frasa kecil seperti 'maaf menyela' menunjukkan kesadaran bahwa kamu mengubah arah percakapan, sama seperti di dunia nyata.",hint:"Beri peringatan sopan, atau langsung ganti / paksa dengan pesan berulang?"},
{n:37,type:"tf",micro:"Etiket membantu percakapan lebih lancar",q:"Benar atau Salah: Etiket digital hanya soal formalitas kosong & tidak benar-benar berpengaruh pada kelancaran atau kesalahpahaman dalam percakapan.",answer:false,explain:"Sebaliknya, etiket adalah alat praktis yang mengurangi gesekan & salah paham dalam komunikasi yang minim isyarat non-verbal, sehingga percakapan online jadi lebih lancar.",hint:"Membuat komunikasi lebih lancar, atau hanya formalitas kosong?"},
{n:38,type:"mcq",micro:"Menanggapi pesan yang tidak jelas maksudnya",q:"Kalau pesan seseorang ambigu & bisa disalahartikan sebagai kasar, sikap yang bijak sebelum bereaksi:",options:["Langsung marah karena merasa dihina","Membalas dengan sindiran serupa","Tanya klarifikasi dengan baik ('maksudnya gimana ya?') daripada langsung berasumsi & marah"],answer:2,explain:"Karena teks mudah disalahpahami, klarifikasi sebelum bereaksi mencegah konflik yang sebenarnya tidak perlu terjadi.",hint:"Klarifikasi dulu, atau langsung marah / sindir balik?"},
{n:39,type:"mcq",micro:"Etiket komentar di unggahan orang lain",q:"Sebelum berkomentar di unggahan seseorang, pertimbangan yang baik:",options:["Apakah komentarmu membangun/relevan, atau hanya untuk merendahkan tanpa alasan jelas","Komentar apa pun boleh selama itu pendapatmu","Selalu berkomentar negatif untuk 'jujur'"],answer:0,explain:"Kejujuran & kesopanan bisa berjalan bersama. Kritik yang membangun berbeda dari komentar yang sekadar merendahkan.",hint:"Pertimbangkan apakah membangun, atau bebas komentar apa saja?"},
{n:40,type:"open",micro:"Menangani grup chat yang ramai & mengganggu",q:"Grup chat kelasmu dipakai untuk hal-hal di luar tugas (bercanda berlebihan, spam stiker, saling menyindir) sampai mengganggu yang butuh info penting. Tulis: (a) 3 masalah etiket yang terjadi, (b) pesan yang akan kamu tulis untuk mengingatkan grup dengan sopan (bukan menggurui), (c) satu usul aturan grup yang bisa disepakati bersama.",sample:"(a) Masalah etiket: (1) Spam stiker & pesan bercanda berlebihan membanjiri notifikasi, membuat info penting (tugas, pengumuman) mudah terlewat/tenggelam. (2) Saling menyindir yang bisa menyakiti perasaan sebagian anggota, meski maksudnya bercanda. (3) Percakapan pribadi berkepanjangan antara dua-tiga orang yang tidak relevan untuk semua anggota grup. (b) Pesan pengingat: 'Hai teman-teman, aku notice belakangan ini chat grup rame banget sampai info tugas suka ketimbun 😅 Gimana kalau kita jaga grup ini khusus buat info penting aja, & kalau mau ngobrol santai/bercanda bisa lanjut di chat pribadi/grup lain? Biar semua nggak ketinggalan info penting juga. Makasih ya!' (nada ramah, tidak menyalahkan siapa pun secara spesifik, & memberi solusi bukan hanya larangan). (c) Usul aturan grup: sepakati grup ini hanya untuk info tugas/pengumuman resmi & pertanyaan terkait pelajaran; buat grup terpisah (opsional, siapa yang mau) untuk obrolan santai/bercanda, supaya yang butuh info cepat tidak perlu menelusuri banyak pesan tidak relevan.",explain:"Jawaban baik: 3 masalah etiket yang spesifik & berbeda (bukan generik 'ramai'), pesan pengingat yang ramah & memberi solusi (bukan menggurui atau menyalahkan), & usul aturan yang konkret & bisa disepakati bersama, bukan sekadar 'jangan berisik'.",hint:"Pesan pengingat (b) harus terdengar seperti dari teman yang peduli, bukan seperti guru yang menghukum, itu kuncinya agar diterima baik."},

// FASE C — PENERAPAN (41-60): praktik komunikasi digital yang baik
{n:41,type:"mcq",micro:"Menulis pesan yang efisien & jelas",q:"Pesan yang baik untuk meminta bantuan biasanya menyebutkan...",options:["Cerita sangat panjang tanpa inti yang jelas","Konteks singkat, apa yang dibutuhkan, & kapan (bila ada tenggat), sehingga penerima langsung paham tanpa perlu banyak tanya balik","Hanya 'Halo, ada waktu?' tanpa detail apa pun"],answer:1,explain:"Pesan yang jelas & lengkap menghormati waktu penerima karena mereka tidak perlu bolak-balik bertanya detail.",hint:"Konteks + kebutuhan + tenggat, atau tanpa detail / terlalu panjang tanpa inti?"},
{n:42,type:"mcq",micro:"Menghindari 'membaca tapi tidak membalas' yang lama",q:"Kalau kamu sudah membaca pesan tapi belum sempat membalas dengan lengkap, kebiasaan yang membantu:",options:["Biarkan tanpa kabar sampai kamu sempat membalas lengkap","Tandai sebagai belum dibaca supaya terlihat belum sempat","Kirim balasan singkat 'sudah baca, nanti kubalas lebih lengkap ya' supaya pengirim tidak menunggu tanpa kepastian"],answer:2,explain:"Konfirmasi singkat mengurangi kecemasan pengirim yang menunggu tanpa tahu apakah pesannya sudah dilihat.",hint:"Beri konfirmasi singkat, atau biarkan tanpa kabar / berpura-pura belum baca?"},
{n:43,type:"mcq",micro:"Etiket berbagi konten sensitif",q:"Sebelum membagikan foto/video yang menampilkan orang lain dalam situasi canggung/lucu, pertimbangan yang etis:",options:["Apakah orang itu akan merasa nyaman kalau tahu ini dibagikan? Tanya izin bila memungkinkan","Bagikan saja karena lucu bagi banyak orang","Tidak perlu memikirkan perasaan orang di dalamnya"],answer:0,explain:"Kelucuan bagi kita tidak selalu sama dengan kenyamanan bagi orang yang menjadi objeknya. Memikirkan perasaannya adalah etiket dasar.",hint:"Pertimbangkan kenyamanan & minta izin, atau bagikan tanpa pikir?"},
{n:44,type:"mcq",micro:"Menanggapi pesan yang salah kirim",q:"Kalau kamu menerima pesan yang jelas-jelas ditujukan untuk orang lain (salah kirim), etiket yang baik:",options:["Simpan & sebarkan isinya karena menarik","Beri tahu dengan baik bahwa pesan itu salah kirim, & jangan menyebarkan isinya ke orang lain","Balas seolah pesan itu untukmu untuk iseng"],answer:1,explain:"Memberi tahu dengan baik membantu pengirim & menghormati privasi mereka, alih-alih memanfaatkan kesalahan itu.",hint:"Beri tahu baik-baik & jangan sebar, atau iseng balas / sebarkan?"},
{n:45,type:"tf",micro:"Kesabaran dalam antrean daring",q:"Benar atau Salah: Aturan menunggu giliran dengan sabar hanya berlaku di dunia nyata; secara daring tidak perlu dipikirkan.",answer:false,explain:"Sebaliknya, prinsip menunggu giliran & tidak menyerobot tetap berlaku secara daring juga (mis. giliran bicara di rapat daring, obrolan bergilir).",hint:"Tetap berlaku secara daring, atau hanya berlaku di dunia nyata?"},
{n:46,type:"mcq",micro:"Mengucapkan terima kasih",q:"Kebiasaan mengucapkan terima kasih setelah dibantu secara daring (dijawab pertanyaan, dikirimi file) sama pentingnya dengan di dunia nyata karena...",options:["Tidak penting karena hanya lewat teks","Hanya perlu untuk bantuan besar, bukan bantuan kecil","Menunjukkan penghargaan atas usaha orang lain, membuat mereka lebih senang membantu di lain waktu"],answer:2,explain:"Ucapan terima kasih kecil membangun hubungan yang baik & membuat kolaborasi terasa lebih hangat, sekecil apa pun bantuannya.",hint:"Menunjukkan penghargaan & membangun hubungan baik, atau tidak penting?"},
{n:47,type:"mcq",micro:"Etiket saat berbagi layar",q:"Sebelum berbagi layar (screen share) saat panggilan daring, kebiasaan yang aman & sopan:",options:["Tutup tab/notifikasi pribadi yang tidak ingin dilihat orang lain terlebih dahulu","Langsung bagikan layar apa adanya tanpa pengecekan","Selalu membagikan seluruh layar termasuk pesan pribadi"],answer:0,explain:"Memeriksa dulu apa yang akan terlihat mencegah kebocoran info pribadi & menjaga fokus pada yang relevan.",hint:"Periksa & tutup yang pribadi dulu, atau bagikan apa adanya?"},
{n:48,type:"mcq",micro:"Menyampaikan ketidaksetujuan dengan sopan",q:"Cara menyampaikan ketidaksetujuan pada pendapat seseorang secara daring dengan sopan:",options:["Diam saja meski tidak setuju demi menghindari konflik","Fokus pada gagasan ('menurutku ada sudut pandang lain...') bukan menyerang orangnya","'Pendapatmu itu bodoh.'"],answer:1,explain:"Kritik terhadap ide bisa disampaikan dengan hormat. Menyerang pribadi berbeda dari mendiskusikan gagasan.",hint:"Fokus pada gagasan dengan hormat, atau menyerang pribadi / diam saja?"},
{n:49,type:"mcq",micro:"Menghindari 'ghosting' yang tidak perlu",q:"Tiba-tiba berhenti membalas tanpa penjelasan (ghosting) pada percakapan yang masih berlangsung penting, dibanding memberi tahu kalau sedang sibuk, biasanya...",options:["Selalu cara terbaik mengakhiri percakapan","Tidak berpengaruh pada perasaan orang lain","Kurang sopan & bisa membuat orang lain khawatir/bingung; memberi tahu singkat lebih baik"],answer:2,explain:"Sedikit pemberitahuan ('aku sibuk dulu ya, nanti lanjut') jauh lebih menghormati daripada menghilang tanpa kabar.",hint:"Kurang sopan & bikin bingung, atau selalu cara terbaik?"},
{n:50,type:"order",micro:"Menyampaikan kritik yang membangun secara daring",q:"Urutkan langkah menyampaikan kritik/masukan secara daring dengan baik.",items:["Pastikan niatmu membantu, bukan menjatuhkan","Sampaikan lewat pesan pribadi bila menyangkut hal sensitif, bukan komentar publik","Fokus pada hal spesifik & beri usul perbaikan, bukan cuma mengeluh","Sampaikan dengan nada yang ramah & terbuka pada diskusi balik"],answer:[0,1,2,3],explain:"Niat baik → kanal yang tepat (privat untuk hal sensitif) → spesifik & solutif → nada ramah. Kritik yang membangun mempertimbangkan cara & tempatnya.",hint:"Memilih kanal privat/publik dilakukan sebelum atau sesudah memastikan niat baik?"},
{n:51,type:"mcq",micro:"Etiket saat menerima kritik",q:"Saat menerima kritik yang disampaikan dengan sopan, respons yang matang:",options:["Dengarkan, pertimbangkan, & tanggapi dengan tenang, meski awalnya terasa tidak nyaman","Langsung membela diri tanpa mendengarkan","Menyerang balik orang yang mengkritik"],answer:0,explain:"Menerima kritik dengan terbuka (bukan berarti selalu setuju) adalah bagian etiket yang membuat diskusi tetap sehat.",hint:"Dengarkan & pertimbangkan dengan tenang, atau membela diri / menyerang balik?"},
{n:52,type:"tf",micro:"Etiket saat mengunggah untuk audiens beragam",q:"Benar atau Salah: Saat memposting sesuatu untuk audiens beragam (usia, latar belakang), tidak perlu mempertimbangkan bahasa & konten sama sekali.",answer:false,explain:"Sebaliknya, konten publik dilihat orang dengan latar berbeda-beda. Mempertimbangkan bahasa & konten yang sesuai untuk semua adalah bagian dari etiket digital yang baik.",hint:"Bagian dari etiket yang baik, atau tidak perlu dipikirkan?"},
{n:53,type:"mcq",micro:"Mengelola kesan pertama daring",q:"Cara memberi kesan pertama yang baik saat bergabung ke grup/komunitas baru secara daring:",options:["Diam total & tidak pernah berinteraksi","Perkenalkan diri singkat, baca dulu aturan/kebiasaan grup sebelum banyak berkomentar","Langsung banyak berkomentar tanpa memperkenalkan diri"],answer:1,explain:"Memperkenalkan diri & memahami budaya grup dulu menunjukkan kesopanan & membantu berbaur dengan baik.",hint:"Perkenalkan diri & pahami aturan dulu, atau langsung ramai / diam total?"},
{n:54,type:"mcq",micro:"Menandai waktu luang & sibuk",q:"Memberi status/keterangan singkat ('sedang belajar, balas nanti malam') membantu karena...",options:["Tidak ada manfaatnya sama sekali","Membuat orang lain merasa diabaikan","Orang lain tahu untuk tidak berharap balasan cepat, mengurangi kesalahpahaman"],answer:2,explain:"Komunikasi tentang ketersediaan diri mengurangi kecemasan orang yang menunggu & menunjukkan kamu menghargai mereka meski sedang sibuk.",hint:"Mengurangi kesalahpahaman soal waktu balas, atau tak bermanfaat?"},
{n:55,type:"mcq",micro:"Etiket dalam diskusi kelompok tugas",q:"Dalam grup tugas kelompok, kebiasaan yang menjaga etiket & kerja sama:",options:["Konfirmasi kesepakatan secara tertulis di grup agar semua ingat & bisa dirujuk kembali","Membuat kesepakatan lisan tanpa dicatat lalu berharap semua ingat","Tidak pernah mengonfirmasi apa pun, berjalan sesuai tebakan masing-masing"],answer:0,explain:"Mencatat kesepakatan (siapa mengerjakan apa, kapan) di tempat yang bisa dilihat semua mengurangi salah paham & pertengkaran nanti.",hint:"Konfirmasi tertulis, atau lisan tanpa catatan / tanpa kesepakatan?"},
{n:56,type:"tf",micro:"Etiket membantu kolaborasi jarak jauh",q:"Benar atau Salah: Etiket digital jadi kurang relevan saat bekerja sama dengan orang yang tidak bisa bertemu langsung, karena semuanya lewat teks/pesan saja.",answer:false,explain:"Sebaliknya, tanpa pertemuan langsung, kejelasan & kesopanan komunikasi tertulis justru jadi fondasi utama kerja sama yang lancar, sehingga etiket makin penting.",hint:"Makin penting untuk kolaborasi jarak jauh, atau kurang relevan?"},
{n:57,type:"mcq",micro:"Menanggapi pesan yang terlambat dibalas orang lain",q:"Kalau seseorang membalas pesanmu lebih lama dari biasanya, sikap yang dewasa:",options:["Kirim pesan berulang-ulang menuntut balasan segera","Beri mereka manfaat keraguan (mungkin sibuk), tanya baik-baik bila memang mendesak, tanpa langsung menuduh mengabaikan","Langsung marah & menuduh mereka sengaja mengabaikan"],answer:1,explain:"Asumsi negatif sering keliru & merusak hubungan tanpa alasan jelas. Memberi ruang & bertanya baik-baik lebih bijak.",hint:"Beri manfaat keraguan & tanya baik-baik, atau langsung marah / desak berulang?"},
{n:58,type:"mcq",micro:"Menjaga etiket saat berdebat topik serius",q:"Saat berdiskusi topik yang bisa memicu emosi (politik, isu sosial) secara daring, kebiasaan yang menjaga etiket:",options:["Menyerang balik siapa pun yang tidak sependapat","Menghindari topik apa pun yang mungkin sensitif selamanya","Fokus pada argumen & bukti, hindari menyerang pribadi, & tahu kapan berhenti bila sudah tidak produktif"],answer:2,explain:"Diskusi yang sehat tetap mungkin untuk topik sulit, selama fokusnya argumen & ada kesadaran kapan harus berhenti.",hint:"Fokus argumen & tahu kapan berhenti, atau menyerang pribadi / hindari semua topik?"},
{n:59,type:"mcq",micro:"Etiket menghargai waktu dalam rapat/kelas daring",q:"Datang tepat waktu ke kelas/rapat daring (bukan telat karena 'kan online, santai') menunjukkan...",options:["Menghargai waktu orang lain sama seperti pertemuan tatap muka","Tidak penting karena semua bisa direkam","Hanya penting untuk pertemuan tatap muka, bukan daring"],answer:0,explain:"Kesan bahwa 'daring = lebih santai soal waktu' sering keliru; menghargai waktu tetap penting di kedua bentuk pertemuan.",hint:"Menghargai waktu sama pentingnya, atau tidak penting karena online?"},
{n:60,type:"open",micro:"Menulis panduan etiket kolaborasi",q:"Kelompokmu akan mengerjakan proyek bersama secara daring selama sebulan (chat, video call, berbagi dokumen). Buat 'panduan etiket kolaborasi' berisi minimal 6 kesepakatan konkret yang akan membuat kerja sama lancar & saling menghormati.",sample:"Panduan Etiket Kolaborasi Kelompok: (1) Semua pesan penting (tugas, jadwal, keputusan) ditulis di grup utama, bukan hanya diobrolkan lisan di video call, supaya tercatat & bisa dirujuk lagi. (2) Balas pesan yang berisi pertanyaan langsung dalam 1x24 jam kalau memungkinkan; kalau sedang sibuk, kirim balasan singkat 'sudah baca, nanti kubalas lebih lengkap'. (3) Untuk video call, konfirmasi kehadiran sehari sebelumnya & datang tepat waktu; kalau berhalangan, kabari sesegera mungkin, bukan mendadak. (4) Saat memberi masukan pada pekerjaan teman, fokus pada bagian yang bisa diperbaiki & sertakan usul konkret, bukan hanya kritik tanpa solusi. (5) Perbedaan pendapat dibahas dengan tenang & fokus pada ide, bukan menyerang orangnya; kalau memanas, jeda dulu sebelum lanjut membahas. (6) Setiap orang wajib mengucap terima kasih & mengakui kontribusi anggota lain saat pekerjaan selesai, tidak ada yang mengklaim seluruh hasil sebagai usahanya sendiri. (7) Hindari mengirim pesan tugas mendadak larut malam yang menuntut balasan segera, kecuali benar-benar darurat.",explain:"Jawaban baik: minimal 6 kesepakatan yang konkret & bisa benar-benar dijalankan (bukan sekadar 'saling menghormati'), mencakup berbagai aspek (kecepatan balas, video call, kritik, konflik, pengakuan kontribusi, waktu), yang menunjukkan pemahaman tentang etiket digital dalam konteks kerja sama nyata.",hint:"Buat tiap poin cukup spesifik sehingga bisa dijadikan acuan saat ada perselisihan, bukan kalimat umum yang bisa diartikan macam-macam."},

// FASE D — PENALARAN (61-80): perbedaan konteks, kesalahpahaman, budaya
{n:61,type:"mcq",micro:"Perbedaan norma antar komunitas",q:"Sebuah kebiasaan yang wajar di satu komunitas daring (mis. bahasa kasar bercanda) bisa dianggap tidak sopan di komunitas lain. Sikap yang bijak:",options:["Menganggap komunitas yang berbeda pasti salah","Amati & sesuaikan dengan norma komunitas yang kamu masuki, bukan menganggap satu standar berlaku di mana-mana","Selalu memakai gaya yang sama di semua tempat"],answer:1,explain:"Etiket bukan aturan tunggal universal untuk semua konteks; kepekaan membaca norma komunitas tertentu itu penting.",hint:"Sesuaikan dengan norma komunitas, atau selalu sama / anggap yang berbeda salah?"},
{n:62,type:"mcq",micro:"Perbedaan budaya & gaya komunikasi",q:"Gaya komunikasi yang dianggap sopan bisa berbeda antar budaya (langsung vs tidak langsung, formal vs santai). Kesadaran ini membantu kita...",options:["Menganggap satu gaya budaya sebagai satu-satunya yang benar","Menghindari berkomunikasi dengan orang dari budaya berbeda","Tidak buru-buru menilai seseorang 'kasar' hanya karena gaya komunikasinya berbeda dari yang biasa kita kenal"],answer:2,explain:"Memahami keberagaman gaya komunikasi mencegah kesalahpahaman yang sebenarnya hanya soal perbedaan kebiasaan, bukan niat buruk.",hint:"Tidak buru-buru menilai kasar, atau anggap satu gaya paling benar?"},
{n:63,type:"mcq",micro:"Kesalahpahaman lewat teks",q:"Kalau pesanmu disalahpahami & membuat orang lain tersinggung padahal tidak bermaksud begitu, langkah yang baik:",options:["Klarifikasi maksud sebenarnya & minta maaf atas kesalahpahamannya, tanpa menyalahkan orang itu karena 'terlalu sensitif'","Diam saja karena itu 'bukan salahmu'","Marah karena merasa disalahpahami"],answer:0,explain:"Meski kesalahpahaman bisa terjadi karena keterbatasan teks, tetap perlu diklarifikasi dengan baik, bukan menyalahkan penerima.",hint:"Klarifikasi & minta maaf, atau diam / marah?"},
{n:64,type:"tf",micro:"Nada bisa disalahartikan karena keterbatasan teks",q:"Benar atau Salah: Sebuah pesan yang dimaksudkan santai bisa terbaca serius/kasar oleh penerima karena teks tidak membawa nada suara asli si pengirim.",answer:true,explain:"Ini alasan utama kenapa membaca ulang & mempertimbangkan bagaimana pesan mungkin dibaca orang lain itu penting.",hint:"Bisa disalahartikan karena tanpa nada suara, atau selalu terbaca sesuai maksud?"},
{n:65,type:"mcq",micro:"Kapan pindah dari teks ke suara/tatap muka",q:"Percakapan sensitif atau rumit (konflik, masalah pribadi) sebaiknya dipindah dari chat ke...",options:["Media sosial publik supaya semua tahu","Panggilan suara/video atau tatap muka, karena nada & ekspresi membantu mengurangi kesalahpahaman untuk topik yang rumit","Selalu tetap di chat teks karena lebih mudah"],answer:1,explain:"Untuk topik yang butuh nuansa (nada, empati, klarifikasi cepat), komunikasi langsung sering jauh lebih efektif daripada teks.",hint:"Pindah ke suara/tatap muka untuk topik rumit, atau tetap teks / buka ke publik?"},
{n:66,type:"mcq",micro:"Etiket saat berbeda zona waktu",q:"Saat berkomunikasi dengan orang di zona waktu berbeda, etiket yang baik:",options:["Anggap semua orang di zona waktu yang sama denganmu","Selalu kirim kapan pun tanpa mempertimbangkan waktu mereka","Pertimbangkan waktu setempat mereka sebelum mengharapkan balasan cepat, & sebutkan bila memang mendesak"],answer:2,explain:"Kesadaran akan perbedaan waktu adalah bentuk penghormatan sederhana pada kehidupan orang di tempat lain.",hint:"Pertimbangkan waktu setempat mereka, atau anggap sama / abaikan?"},
{n:67,type:"mcq",micro:"Etiket & kesehatan mental orang lain",q:"Memperhatikan bahwa seseorang tampak kesulitan/sedih dari nada pesannya & menanyakan keadaannya dengan baik adalah...",options:["Bentuk kepedulian yang juga bagian dari etiket digital yang baik, bukan hanya soal formalitas bahasa","Bukan urusan kita sama sekali","Hanya perlu dilakukan tatap muka, tidak relevan secara daring"],answer:0,explain:"Etiket digital yang matang mencakup kepekaan pada kesejahteraan orang lain, tidak hanya aturan menulis yang sopan.",hint:"Bentuk kepedulian & bagian etiket, atau bukan urusan kita?"},
{n:68,type:"tf",micro:"Etiket berkembang seiring teknologi baru",q:"Benar atau Salah: Norma etiket digital terus berkembang seiring munculnya platform & fitur baru, jadi kebiasaan baik perlu terus disesuaikan, bukan dianggap tetap selamanya.",answer:true,explain:"Etiket email berbeda dari etiket pesan singkat, & keduanya bisa berbeda dari etiket platform baru. Kepekaan pada perubahan ini penting.",hint:"Terus berkembang & perlu disesuaikan, atau tetap sama selamanya?"},
{n:69,type:"mcq",micro:"Menahan diri dari membalas saat emosi",q:"Kalau kamu membaca pesan yang membuatmu marah, kebiasaan yang bijak sebelum membalas:",options:["Balas dengan kalimat yang sengaja menyakiti balik","Tunggu sampai lebih tenang sebelum menulis balasan, karena balasan saat emosi sering disesali kemudian","Balas secepat mungkin selagi emosinya masih terasa"],answer:1,explain:"Sama seperti unggahan, balasan yang ditulis saat sangat emosional sering lebih kasar dari yang sebenarnya dimaksud & sulit ditarik kembali.",hint:"Tunggu tenang dulu, atau balas segera saat emosi?"},
{n:70,type:"tf",micro:"Etiket bukan tentang selalu setuju",q:"Benar atau Salah: Etiket digital yang baik tidak berarti selalu setuju dengan semua orang; kamu tetap boleh tidak setuju, asal disampaikan dengan cara yang menghormati.",answer:true,explain:"Etiket mengatur CARA berkomunikasi, bukan mengharuskan kita selalu sepakat. Ketidaksetujuan yang sopan tetap sehat.",hint:"Boleh tidak setuju dengan cara sopan, atau harus selalu setuju?"},
{n:71,type:"mcq",micro:"Menyeimbangkan kejujuran & kesopanan",q:"Memberi tahu teman bahwa karyanya perlu banyak perbaikan, dengan cara yang jujur sekaligus sopan, berarti...",options:["Selalu berbohong demi menjaga perasaan","Selalu blak-blakan tanpa mempertimbangkan cara penyampaian","Menyampaikan hal yang benar tapi dengan cara yang membangun & menghargai perasaannya, bukan berbohong atau bersikap kasar"],answer:2,explain:"Jujur & sopan bukan dua hal yang bertentangan. Cara menyampaikan kebenaran bisa dipilih agar tetap menghormati.",hint:"Jujur & sopan bersama, atau berbohong / kasar tanpa filter?"},
{n:72,type:"mcq",micro:"Etiket saat menerima permintaan maaf",q:"Kalau seseorang meminta maaf dengan tulus atas kesalahannya secara daring, respons yang matang:",options:["Terima dengan baik bila kamu memang sudah siap, atau jelaskan dengan jujur bila masih butuh waktu, tanpa harus berpura-pura baik-baik saja","Selalu harus langsung memaafkan sepenuhnya saat itu juga","Mengabaikan permintaan maaf sepenuhnya"],answer:0,explain:"Menerima permintaan maaf adalah proses yang jujur, tidak harus dipaksakan instan, tapi juga tidak perlu diabaikan begitu saja.",hint:"Jujur sesuai kesiapan diri, atau harus langsung maafkan / abaikan?"},
{n:73,type:"mcq",micro:"Etiket & kesetaraan dalam diskusi",q:"Dalam diskusi kelompok daring, memastikan semua anggota (termasuk yang pendiam) punya kesempatan bicara adalah...",options:["Hanya tanggung jawab pemimpin diskusi, bukan anggota lain","Bagian dari etiket yang menghargai kesetaraan & keberagaman suara, bukan hanya soal sopan santun individu","Tidak berhubungan dengan etiket sama sekali"],answer:1,explain:"Etiket digital yang matang mencakup kesadaran kolektif: semua anggota, bukan hanya pemimpin, bisa membantu menciptakan ruang yang setara.",hint:"Bagian dari menghargai kesetaraan suara, atau tak berhubungan / hanya tugas pemimpin?"},
{n:74,type:"mcq",micro:"Etiket saat berbagi pendapat kontroversial",q:"Sebelum membagikan pendapat yang berpotensi memicu perdebatan panas, pertimbangan yang matang:",options:["Bagikan kapan pun tanpa memikirkan konteks","Hindari sepenuhnya menyampaikan pendapat apa pun","Apakah ini tempat & waktu yang tepat, & apakah aku siap berdiskusi dengan tenang bila ada yang tidak setuju"],answer:2,explain:"Bukan berarti tidak boleh berpendapat, tapi mempertimbangkan konteks & kesiapan diri untuk diskusi yang mungkin menantang.",hint:"Pertimbangkan konteks & kesiapan diri, atau bagikan tanpa pikir / hindari total?"},
{n:75,type:"order",micro:"Menangani kesalahpahaman teks yang meningkat",q:"Urutkan langkah menangani kesalahpahaman yang mulai memanas lewat chat.",items:["Sadari bahwa situasinya mulai memanas & teks membatasi pemahaman satu sama lain","Usulkan pindah ke panggilan suara/video atau bertemu langsung","Dengarkan sudut pandang satu sama lain dengan tenang saat bicara langsung","Setelah tenang, sepakati cara menghindari kesalahpahaman serupa ke depan"],answer:[0,1,2,3],explain:"Sadari batasan teks → pindah ke komunikasi langsung → dengarkan dengan tenang → sepakati pencegahan ke depan. Memindahkan kanal komunikasi sering jadi kunci meredakan situasi.",hint:"Mengusulkan pindah kanal dilakukan sebelum atau sesudah situasi makin memanas di teks?"},
{n:76,type:"tf",micro:"Etiket melindungi hubungan jangka panjang",q:"Benar atau Salah: Menjaga etiket digital yang baik membantu menjaga hubungan (pertemanan, keluarga, kerja) tetap sehat dalam jangka panjang, karena komunikasi digital kini jadi bagian besar dari interaksi kita.",answer:true,explain:"Karena begitu banyak interaksi kini terjadi lewat layar, kebiasaan komunikasi yang baik di sana ikut membentuk kualitas hubungan secara keseluruhan.",hint:"Membantu menjaga hubungan jangka panjang, atau tidak berpengaruh?"},
{n:77,type:"mcq",micro:"Etiket & rasa aman berpendapat",q:"Komunitas daring dengan etiket yang baik (saling menghormati meski berbeda pendapat) cenderung membuat anggotanya...",options:["Lebih berani berbagi ide & bertanya, karena tidak takut diserang atau dipermalukan","Menjadi pasif & tidak pernah berpendapat","Tidak berpengaruh pada keberanian berbicara"],answer:0,explain:"Rasa aman psikologis (dibangun lewat etiket yang baik) mendorong partisipasi yang lebih kaya & jujur dari semua anggota.",hint:"Lebih berani berbagi ide, atau jadi pasif / tak berpengaruh?"},
{n:78,type:"mcq",micro:"Etiket sebagai kebiasaan, bukan hafalan aturan",q:"Cara terbaik menginternalisasi etiket digital:",options:["Mengabaikan etiket karena terlalu rumit untuk dipikirkan","Membiasakan diri bertanya 'bagaimana perasaanku kalau menerima pesan seperti ini?' sebelum mengirim, bukan menghafal daftar aturan panjang","Menghafal semua aturan tertulis tanpa memahami alasannya"],answer:1,explain:"Empati praktis (membayangkan diri di posisi penerima) lebih fleksibel & tahan lama daripada menghafal aturan kaku untuk tiap situasi.",hint:"Membiasakan empati praktis, atau menghafal daftar aturan / mengabaikan?"},
{n:79,type:"mcq",micro:"Etiket & keberagaman kemampuan",q:"Mempertimbangkan bahwa tidak semua orang bisa membaca pesan panjang dengan cepat, atau memahami singkatan/istilah tertentu, adalah bagian dari...",options:["Tidak relevan dengan etiket berkomunikasi","Hanya perlu dipikirkan untuk pesan resmi, bukan sehari-hari","Kepekaan & inklusivitas dalam berkomunikasi, membuat pesan bisa dipahami lebih banyak orang"],answer:2,explain:"Menulis dengan jelas & mempertimbangkan siapa yang membaca (termasuk yang mungkin kesulitan dengan istilah tertentu) adalah bentuk etiket yang inklusif.",hint:"Bagian dari kepekaan & inklusivitas, atau tak relevan?"},
{n:80,type:"open",micro:"Menyelesaikan kesalahpahaman lewat teks",q:"Kamu mengirim pesan bercanda ke teman, tapi dia membalas dengan nada marah karena mengira kamu menyindirnya. Tulis: (a) bagaimana kamu akan merespons pertama kali (kalimat konkret), (b) kenapa penting tidak langsung membela diri atau marah balik, (c) bagaimana kamu akan mencegah kesalahpahaman serupa di masa depan dengan teman ini.",sample:"(a) Respons pertama: 'Eh, maaf ya kalau kedengarannya begitu, sama sekali nggak maksud nyindir kok. Aku becanda soal [jelaskan konteksnya]. Kamu nggak apa-apa?' (langsung klarifikasi maksud + tunjukkan kepedulian, bukan membela diri secara defensif). (b) Kenapa penting tidak langsung membela diri/marah balik: kalau aku langsung membela diri ('lah aku kan cuma bercanda, kok baper') atau marah balik, itu akan membuatnya makin merasa tidak didengar & situasi bisa memanas jadi pertengkaran yang sebenarnya tidak perlu terjadi, padahal ini murni kesalahpahaman karena teks tidak membawa nada suara & ekspresi wajahku saat 'bercanda'. Fokus pertama harusnya meredakan & memastikan dia mengerti maksudku, bukan membuktikan diriku benar. (c) Mencegah ke depan: aku akan lebih hati-hati memakai emoji atau kata tambahan (mis. 'wkwk', '😂') saat bercanda lewat teks dengannya, terutama untuk topik yang sensitif baginya; kalau aku merasa leluconnya bisa disalahartikan, aku akan menyampaikannya langsung/lewat suara daripada teks singkat yang rawan disalahpahami, atau menanyakan dulu 'boleh becanda soal ini nggak?'",explain:"Jawaban baik: respons pertama yang benar-benar meredakan (klarifikasi + kepedulian, bukan defensif), penjelasan yang jelas kenapa membela diri/marah balik memperburuk keadaan, & rencana konkret mencegah kesalahpahaman serupa (bukan sekadar 'akan lebih hati-hati').",hint:"Bagian (a) jangan sampai terdengar seperti membela diri ('aku kan cuma bercanda'), fokuskan pada memastikan temanmu merasa didengar dulu."},

// FASE E — TANTANGAN (81-100): skenario & kapstone
{n:81,type:"mcq",micro:"Skenario: guru membalas lambat",q:"Kamu mengirim pertanyaan penting ke guru lewat pesan & belum dibalas setelah 2 hari. Sikap yang sopan:",options:["Kirim pengingat yang sopan ('Selamat pagi Bu, mohon maaf mengingatkan lagi soal pertanyaan kemarin, terima kasih') tanpa terdengar menuntut","Kirim pesan berulang setiap jam menuntut jawaban","Anggap guru sengaja mengabaikan & bersikap dingin di kelas"],answer:0,explain:"Mengingatkan dengan sopan wajar & membantu; menuntut atau berasumsi buruk tanpa dasar tidak produktif.",hint:"Ingatkan sopan sekali, atau desak berulang / berasumsi buruk?"},
{n:82,type:"mcq",micro:"Skenario: candaan yang ternyata menyakiti",q:"Kamu bercanda di grup & ternyata membuat satu teman diam-diam sedih, meski tidak langsung bilang. Kamu menyadarinya dari nada balasannya yang berubah. Langkah yang baik:",options:["Menunggu dia yang bicara duluan tanpa kamu bertindak apa pun","Tanya secara pribadi apakah candaanmu tadi menyinggung, & minta maaf bila memang begitu","Anggap dia terlalu sensitif & lanjutkan seperti biasa"],answer:1,explain:"Peka pada perubahan nada & berinisiatif menanyakan/minta maaf menunjukkan kepedulian yang sesungguhnya, bukan menunggu pasif.",hint:"Tanya & minta maaf secara pribadi, atau abaikan / tunggu pasif?"},
{n:83,type:"mcq",micro:"Skenario: rapat daring yang berantakan",q:"Saat presentasi kelompok daring, salah satu anggota terus bicara tanpa memberi kesempatan yang lain. Sebagai anggota lain, sikap yang membantu:",options:["Memotong dengan kasar di depan semua peserta","Diam saja meski merasa tidak adil","Cari celah sopan untuk mengarahkan ('terima kasih, mungkin bisa dilanjutkan oleh X untuk bagian berikutnya?')"],answer:2,explain:"Mengarahkan dengan sopan menjaga kelancaran tanpa mempermalukan siapa pun, sambil tetap memastikan semua dapat giliran.",hint:"Arahkan dengan sopan, atau potong kasar / diam saja?"},
{n:84,type:"mcq",micro:"Skenario: menerima pesan kasar dari orang asing",q:"Seseorang yang tidak kamu kenal mengirim pesan kasar tanpa alasan jelas. Respons yang bijak:",options:["Tidak perlu membalas dengan kekasaran serupa; blokir/laporkan bila perlu, & jangan biarkan itu merusak harimu","Balas dengan kekasaran yang sama agar 'seimbang'","Membalas panjang lebar mencoba membuktikan diri benar"],answer:0,explain:"Etiket tidak mengharuskan kita menoleransi pelecehan, tapi juga tidak berarti membalasnya dengan cara yang sama buruknya. Blokir & lanjutkan hidup adalah pilihan sehat.",hint:"Blokir/laporkan tanpa membalas kasar, atau balas kasar / berdebat panjang?"},
{n:85,type:"tf",micro:"Etiket digital adalah keterampilan yang bisa dipelajari",q:"Benar atau Salah: Etiket digital adalah keterampilan yang bisa dipelajari & diperbaiki lewat kesadaran & latihan, bukan bakat bawaan.",answer:true,explain:"Seperti sopan santun pada umumnya, ini dipelajari lewat contoh, kesalahan, & refleksi, bukan sesuatu yang otomatis dimiliki sejak lahir.",hint:"Bisa dipelajari & dilatih, atau bakat bawaan?"},
{n:86,type:"mcq",micro:"Skenario: menyeimbangkan kejujuran & perasaan teman",q:"Temanmu meminta pendapat jujur tentang video yang baru dia buat, tapi menurutmu masih perlu banyak perbaikan. Cara menjawab:",options:["Sebutkan semua kekurangannya tanpa menyebut kelebihannya sama sekali","Sebut hal yang sudah bagus dulu, lalu sampaikan area yang bisa diperbaiki dengan usul konkret, dengan nada mendukung","Bilang 'bagus banget' meski tidak jujur"],answer:1,explain:"Struktur 'apresiasi dulu, lalu masukan konstruktif' membantu kejujuran tersampaikan tanpa terasa menjatuhkan.",hint:"Apresiasi + masukan konstruktif, atau berbohong / hanya sebut kekurangan?"},
{n:87,type:"mcq",micro:"Skenario: grup kerja lintas usia",q:"Kamu bekerja sama dalam grup daring yang beranggotakan orang dari berbagai usia (termasuk orang dewasa yang tidak begitu paham istilah gaul). Penyesuaian yang bijak:",options:["Tetap pakai bahasa gaul & biarkan mereka bertanya sendiri","Berhenti berkomunikasi dengan mereka karena beda generasi","Gunakan bahasa yang lebih umum & jelas, jangan berasumsi semua paham istilah/singkatan tertentu"],answer:2,explain:"Menyesuaikan bahasa untuk audiens yang beragam adalah bentuk etiket yang membuat komunikasi inklusif & efektif untuk semua.",hint:"Gunakan bahasa jelas & umum, atau tetap gaul / hindari komunikasi?"},
{n:88,type:"mcq",micro:"Skenario: pesan yang terlanjur terkirim salah",q:"Kamu tidak sengaja mengirim pesan yang seharusnya untuk orang lain ke grup besar. Langkah yang tepat:",options:["Segera hapus bila memungkinkan, & jelaskan singkat dengan jujur bahwa itu salah kirim","Berpura-pura tidak terjadi apa-apa","Menyalahkan aplikasi karena 'error'"],answer:0,explain:"Kejujuran & tindakan cepat (hapus bila bisa) lebih baik daripada berpura-pura atau mencari kambing hitam yang tidak masuk akal.",hint:"Hapus & jelaskan jujur, atau berpura-pura / menyalahkan aplikasi?"},
{n:89,type:"mcq",micro:"Skenario: menyeimbangkan etiket & membela diri",q:"Seseorang menuduhmu sesuatu yang tidak benar secara publik. Cara membela diri yang tetap sesuai etiket:",options:["Menyerang balik dengan tuduhan lain yang tidak berhubungan","Jelaskan faktanya dengan tenang & jelas, tanpa menyerang balik secara pribadi meski merasa marah","Diam saja & membiarkan tuduhan itu dipercaya semua orang"],answer:1,explain:"Membela diri dengan fakta & ketenangan tetap sesuai etiket, berbeda dari diam pasif atau membalas dengan serangan yang tidak relevan.",hint:"Jelaskan fakta dengan tenang, atau diam saja / menyerang balik?"},
{n:90,type:"order",micro:"Proyek: kode etik komunitas daring",q:"Urutkan langkah membuat 'kode etik' sederhana untuk komunitas/grup daring yang kamu ikuti.",items:["Diskusikan bersama anggota tentang masalah komunikasi yang pernah terjadi","Rumuskan 5-7 aturan konkret berdasarkan masalah yang ditemukan","Bagikan & minta persetujuan semua anggota, jelaskan alasan tiap aturan","Tinjau ulang secara berkala & sesuaikan bila ada masalah baru"],answer:[0,1,2,3],explain:"Diskusi masalah nyata → rumuskan aturan konkret → sepakati bersama dengan alasan → tinjau berkala. Aturan yang lahir dari masalah nyata & disepakati bersama lebih dihormati daripada dipaksakan sepihak.",hint:"Merumuskan aturan konkret sebelum atau sesudah diskusi masalah yang pernah terjadi?"},
{n:91,type:"mcq",micro:"Skenario: menegur anggota keluarga yang kurang sopan online",q:"Kamu melihat anggota keluargamu (misalnya kakak) menulis komentar yang kurang sopan di media sosial. Cara menegur yang menghormati hubungan keluarga:",options:["Membalas komentarnya secara terbuka untuk 'mempermalukannya agar sadar'","Diam saja karena tidak enak menegur keluarga sendiri","Sampaikan secara pribadi dengan baik, bukan menegur di depan umum atau membalas komentarnya secara terbuka"],answer:2,explain:"Menegur secara pribadi tetap menghormati hubungan sambil menyampaikan kepedulian, berbeda dari mempermalukan di depan umum.",hint:"Tegur pribadi dengan baik, atau permalukan publik / diam saja?"},
{n:92,type:"tf",micro:"Etiket digital membentuk budaya online yang sehat",q:"Benar atau Salah: Semakin banyak orang yang mempraktikkan etiket digital yang baik, semakin sehat & nyaman suasana ruang digital secara keseluruhan bagi semua orang.",answer:true,explain:"Etiket individu menumpuk jadi budaya kolektif. Kebiasaan baik yang menyebar luas membuat ruang digital lebih ramah bagi semua.",hint:"Membentuk budaya online yang lebih sehat, atau tidak berpengaruh secara kolektif?"},
{n:93,type:"mcq",micro:"Skenario: menerima pesan dari orang yang sedang marah",q:"Seseorang mengirim pesan yang jelas ditulis saat sedang sangat marah kepadamu. Sikap yang bijak:",options:["Beri mereka waktu tenang dulu sebelum membalas, & tanggapi isinya (bukan nada marahnya) setelah situasi mereda","Membalas dengan kemarahan yang sama saat itu juga","Mengabaikan sepenuhnya tanpa pernah menanggapi"],answer:0,explain:"Membalas saat kedua pihak masih emosi jarang produktif. Memberi jeda & fokus pada isi (bukan nada) setelah tenang lebih efektif.",hint:"Beri jeda & tanggapi isinya setelah tenang, atau balas marah juga / abaikan total?"},
{n:94,type:"mcq",micro:"Skenario: kesalahpahaman lintas generasi",q:"Orang tuamu merasa tersinggung dengan pesan singkat & tanpa emoji darimu, padahal maksudmu netral biasa saja. Cara menjembatani:",options:["Berhenti berkomunikasi lewat teks dengan mereka sama sekali","Jelaskan dengan sabar bahwa gaya menulismu memang singkat tapi tidak bermaksud dingin, & sesekali tambahkan sedikit konteks/emoji untuk mereka","Bilang 'itu cuma perasaan Ibu/Ayah aja' tanpa penjelasan lebih"],answer:1,explain:"Menjembatani perbedaan gaya komunikasi antar generasi butuh penjelasan sabar & sedikit penyesuaian, bukan mengabaikan perasaan mereka.",hint:"Jelaskan sabar & sesuaikan sedikit, atau meremehkan perasaan mereka / berhenti berkomunikasi?"},
{n:95,type:"tf",micro:"Etiket digital adalah perpanjangan karakter",q:"Benar atau Salah: Cara seseorang bersikap secara online (sopan, jujur, menghormati) sering mencerminkan karakter mereka secara keseluruhan, bukan 'kepribadian terpisah' yang bebas aturan.",answer:true,explain:"Layar bukan topeng yang menghapus tanggung jawab moral. Perilaku digital adalah bagian nyata dari karakter seseorang.",hint:"Mencerminkan karakter secara keseluruhan, atau kepribadian terpisah bebas aturan?"},
{n:96,type:"mcq",micro:"Skenario: menjaga suasana positif tanpa menekan kejujuran",q:"Kamu ingin grup tetap positif tapi juga ingin anggota bisa jujur soal masalah. Cara menyeimbangkan:",options:["Larang semua keluhan supaya grup terlihat selalu positif","Biarkan siapa pun mengeluh dengan cara apa pun tanpa batas","Dorong kejujuran yang disampaikan dengan sopan & solutif, bukan melarang keluhan sama sekali demi 'terlihat positif'"],answer:2,explain:"Positif yang sehat bukan berarti menutup mata dari masalah, melainkan membahasnya dengan cara yang membangun.",hint:"Dorong kejujuran yang sopan & solutif, atau larang keluhan / tanpa batas?"},
{n:97,type:"mcq",micro:"Menilai pemahaman diri",q:"Tanda kamu sudah cukup memahami etiket digital:",options:["Kamu terbiasa memikirkan dampak pesanmu sebelum mengirim, menyesuaikan gaya dengan konteks, & bisa menangani kesalahpahaman dengan baik","Kamu hafal daftar 'jangan lakukan ini' tapi tetap bertindak impulsif","Kamu berhenti berkomunikasi secara daring untuk menghindari masalah"],answer:0,explain:"Kemahiran sejati terlihat dari kebiasaan nyata (memikirkan dampak, menyesuaikan konteks, menangani konflik), bukan sekadar hafalan aturan.",hint:"Kebiasaan nyata & bisa menangani kesalahpahaman, atau hafal aturan tanpa berubah / hindari total?"},
{n:98,type:"mcq",micro:"Etiket digital & masyarakat",q:"Ruang digital yang dipenuhi orang-orang dengan etiket baik cenderung menjadi tempat yang...",options:["Justru lebih membosankan tanpa perdebatan","Lebih nyaman untuk berbagi ide, belajar, & terhubung, dibanding ruang yang penuh kekasaran & saling serang","Sama saja tanpa perbedaan berarti"],answer:1,explain:"Kualitas interaksi digital secara keseluruhan sangat dipengaruhi oleh kebiasaan tiap individu di dalamnya.",hint:"Lebih nyaman untuk berbagi & belajar, atau sama saja / membosankan?"},
{n:99,type:"mcq",micro:"Inti keterampilan",q:"Inti dari 'etika & sopan santun digital':",options:["Menghafal semua aturan platform secara harfiah","Menghindari berkomunikasi secara daring sebisa mungkin","Ingat bahwa ada manusia sungguhan di ujung layar; sesuaikan komunikasi dengan konteks & audiens, pikirkan dampak sebelum mengirim, & tangani kesalahpahaman dengan baik"],answer:2,explain:"Ingat ada manusia + sesuaikan konteks + pikirkan dampak + tangani kesalahpahaman dengan baik. Ini prinsip yang berlaku di platform apa pun, kapan pun.",hint:"Ingat ada manusia & pikirkan dampak, atau hafal aturan harfiah / hindari total?"},
{n:100,type:"open",micro:"Kapstone: kode etik digital pribadi",q:"Tulis 'kode etik digital' pribadimu untuk dipegang seterusnya. Sertakan: (a) 5 prinsip yang akan kamu pegang saat berkomunikasi daring, (b) untuk tiap prinsip, contoh tindakan konkret, (c) bagaimana kamu akan menangani diri sendiri saat marah/emosi sebelum membalas pesan, (d) bagaimana kamu akan menangani kesalahpahaman jika itu terjadi, (e) satu komitmen tentang bagaimana kamu ingin diperlakukan orang lain & bagaimana kamu akan memperlakukan orang lain dengan cara yang sama.",sample:"(a) & (b) Prinsip & tindakan: (1) 'Aku memikirkan dampak sebelum mengirim', tindakan, selalu membaca ulang pesan penting & bertanya 'bagaimana kalau ini kubaca sebagai penerima?' sebelum menekan kirim. (2) 'Aku menyesuaikan gaya dengan audiens', tindakan, memakai bahasa lebih formal untuk guru/orang dewasa, & bahasa santai yang tetap sopan untuk teman. (3) 'Aku menghormati waktu & batas orang lain', tindakan, tidak mengharapkan balasan instan & tidak mengirim pesan mendesak di jam istirahat kecuali darurat. (4) 'Aku menyampaikan ketidaksetujuan dengan hormat', tindakan, fokus pada gagasan bukan pribadi saat berbeda pendapat, & memilih pesan pribadi untuk hal sensitif, bukan komentar publik. (5) 'Aku bertanggung jawab atas kesalahanku', tindakan, mengakui & meminta maaf secepatnya bila pesanku menyinggung orang lain, tanpa membela diri dulu. (c) Menangani emosi sebelum membalas: aku akan menutup aplikasi & melakukan hal lain minimal 15 menit sebelum membalas pesan yang membuatku marah, & menulis dulu balasan sebagai draf yang tidak langsung kukirim, baru kubaca ulang setelah lebih tenang untuk melihat apakah masih ingin kukirim seperti itu. (d) Menangani kesalahpahaman: aku akan klarifikasi maksud sebenarnya secepat mungkin, minta maaf atas kesalahpahaman itu (bukan menyalahkan orang lain karena 'salah paham'), & kalau situasinya rumit, aku akan mengusulkan pindah ke panggilan suara/tatap muka daripada terus berdebat lewat teks. (e) Komitmen: aku ingin diperlakukan dengan didengar, dihormati waktuku, & diberi kesempatan menjelaskan sebelum dihakimi; karena itu aku berkomitmen memperlakukan setiap orang yang berkomunikasi denganku, termasuk yang tidak kukenal, dengan cara yang sama, mendengarkan sebelum menilai, & menghormati waktu mereka.",explain:"Jawaban baik: 5 prinsip yang mencakup dampak pesan, penyesuaian konteks, menghormati waktu, ketidaksetujuan yang hormat, & tanggung jawab atas kesalahan, masing-masing dengan tindakan konkret yang benar-benar bisa dilakukan; strategi menahan diri saat emosi yang spesifik (bukan 'akan lebih sabar'); langkah menangani kesalahpahaman yang berurutan & benar; & komitmen timbal balik yang menghubungkan bagaimana ingin diperlakukan dengan bagaimana akan memperlakukan orang lain.",hint:"Bagian (c) sering lemah, buat strategi yang benar-benar konkret & bisa dilakukan (jeda waktu, tulis draf dulu), bukan sekadar 'akan berusaha tenang'."},
];
